import java.util.*;
import java.io.*;

public class Main {
    static final int MAX_N = 10;
    static int size_N;
    static Modular[][] prob_matrix = new Modular[MAX_N][MAX_N];

    static class Modular {
        static final int MOD_CONST = 1000000007;
        int value;

        Modular(long v) {
            v %= MOD_CONST;
            if (v < 0) v += MOD_CONST;
            this.value = (int) v;
        }

        static int extendedGCD(int a, int m, int[] xy) {
            if (m == 0) {
                xy[0] = 1;
                xy[1] = 0;
                return a;
            }
            int[] yx = new int[2];
            int g = extendedGCD(m, a % m, yx);
            int y = yx[0], x = yx[1];
            xy[0] = x;
            xy[1] = y - (a / m) * x;
            return g;
        }

        static int modularInverse(int a) {
            int[] xy = new int[2];
            extendedGCD(a, MOD_CONST, xy);
            int x = xy[0];
            return (x % MOD_CONST + MOD_CONST) % MOD_CONST;
        }

        Modular add(Modular other) {
            int res = this.value + other.value;
            if (res >= MOD_CONST) res -= MOD_CONST;
            return new Modular(res);
        }

        Modular subtract(Modular other) {
            int res = this.value - other.value;
            if (res < 0) res += MOD_CONST;
            return new Modular(res);
        }

        Modular multiply(Modular other) {
            long res = (long) this.value * other.value;
            res %= MOD_CONST;
            return new Modular(res);
        }

        Modular divide(Modular other) {
            return this.multiply(new Modular(modInverse(other.value)));
        }

        static int modInverse(int a) {
            return modularInverse(a);
        }

        Modular pow(long p) {
            assert p >= 0;
            Modular base = this;
            Modular result = new Modular(1);
            while (p > 0) {
                if ((p & 1) == 1) result = result.multiply(base);
                base = base.multiply(base);
                p >>= 1;
            }
            return result;
        }

        @Override
        public String toString() {
            return Integer.toString(value);
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        size_N = Integer.parseInt(st.nextToken());

        for (int i = 0; i < size_N; i++) {
            st = new StringTokenizer(br.readLine());
            for (int j = 0; j < size_N; j++) {
                int p = Integer.parseInt(st.nextToken());
                prob_matrix[i][j] = new Modular(p).divide(new Modular(100));
            }
        }

        List<List<Integer>> count_masks = new ArrayList<>();
        for (int i = 0; i <= size_N; i++) {
            count_masks.add(new ArrayList<>());
        }
        int[] lookup_mask = new int[1 << size_N];
        Arrays.fill(lookup_mask, -1);
        for (int mask = 0; mask < (1 << size_N); mask++) {
            int c = Integer.bitCount(mask);
            lookup_mask[mask] = count_masks.get(c).size();
            count_masks.get(c).add(mask);
        }

        Map<Long, Modular> possible_states = new HashMap<>();
        long initial_mask = 1L << lookup_mask[0];
        possible_states.put(initial_mask, new Modular(1));

        for (int left = 0; left < size_N; left++) {
            Map<Long, Modular> new_states = new HashMap<>();
            Modular[] product_mask = new Modular[1 << size_N];
            Arrays.fill(product_mask, new Modular(1));
            for (int current_mask = 0; current_mask < (1 << size_N); current_mask++) {
                Modular prod = new Modular(1);
                for (int right = 0; right < size_N; right++) {
                    boolean bitSet = ((current_mask >> right) & 1) == 1;
                    Modular factor = bitSet ? prob_matrix[left][right] : new Modular(1).subtract(prob_matrix[left][right]);
                    prod = prod.multiply(factor);
                }
                product_mask[current_mask] = prod;
            }

            long[] new_bits = new long[size_N];
            Arrays.fill(new_bits, 0L);
            Map<Long, Modular> new_possible = new HashMap<>();
            for (Map.Entry<Long, Modular> state : possible_states.entrySet()) {
                long mask_state = state.getKey();
                Modular prob_value = state.getValue();

                Arrays.fill(new_bits, 0L);
                for (int mask : count_masks.get(left)) {
                    if (((mask_state >> lookup_mask[mask]) & 1) == 1) {
                        for (int i = 0; i < size_N; i++) {
                            if (((mask >> i) & 1) == 0) {
                                long new_mask_bit = 1L << lookup_mask[mask | (1 << i)];
                                new_bits[i] |= new_mask_bit;
                            }
                        }
                    }
                }

                // Build new_possible
                for (int current_mask = 1; current_mask < (1 << size_N); current_mask++) {
                    int ctz = Integer.numberOfTrailingZeros(current_mask);
                    long combined_mask = 0L;
                    for (int i = 0; i < size_N; i++) {
                        if (((current_mask >> i) & 1) == 1) {
                            combined_mask |= new_bits[i];
                        }
                    }
                    Modular val = new_possible.getOrDefault(combined_mask, new Modular(0));
                    Modular addVal = prob_value.multiply(product_mask[current_mask]);
                    new_possible.put(combined_mask, val.add(addVal));
                }
            }
            possible_states = new HashMap<>(new_possible);
        }

        Modular answer = new Modular(0);
        int last_mask_index = lookup_mask[(1 << size_N) - 1];
        for (Map.Entry<Long, Modular> state : possible_states.entrySet()) {
            long mask = state.getKey();
            if (((mask >> last_mask_index) & 1) == 1) {
                answer = answer.add(state.getValue());
            }
        }

        System.out.println(answer.value);
    }
}
